class Browser:
    def __init__(self):
      self.links = []  
  
    def is_empty(self):
      return self.links == []
  
    def push(self, link):
      self.links.insert(0, link)

    def pop(self):
      p = self.links[0]
      self.links = self.links[1:]
      return p
  
x = Browser()
x.push('about:blank')
x.push('www.pythontip.com')
x.push('edu.py2fun.com')
x.push('edu.py2fun.com/home')

while not x.is_empty():
    print(x.pop())
